        return head;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        for (int i = 0; i < n; i++) {
            in.nextToken();
            cur.next = new ListNode((long) in.nval);
            cur = cur.next;
        }
        ListNode head = rearrange(dummy.next);
        StringBuilder sb = new StringBuilder();
        while (head != null) {
            sb.append(head.val);
            head = head.next;
            if (head != null) sb.append(' ');
        }
        sb.append('\n');
        System.out.print(sb);
    }
}

